// Normalize the LP payload (URL-encoded form from black-friday/index.html) for GoHighLevel.
const b = $input.first().json.body || {};
const parts = String(b.name || '').trim().split(/\s+/);
const january = b.offer_option === 'january';
const programs = { toddlers: 'Toddlers 3-5', kids: 'Kids 6-14', women: 'Women', fundamentals: 'Fundamentals', advanced: 'Advanced', 'not-sure': 'Not sure yet' };
const program = programs[b.program] || 'Not sure yet';
const option = january ? 'Start in January ($100 deposit)' : 'Start now (November)';
const attribution = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term', 'gclid', 'fbclid', 'landing_page', 'event_id']
  .filter(k => b[k]).map(k => `${k}: ${b[k]}`).join('\n');
return [{ json: {
  firstName: parts[0] || '',
  lastName: parts.slice(1).join(' '),
  email: String(b.email || '').trim().toLowerCase(),
  phone: String(b.phone || '').trim(),
  source: b.source || 'LP Black Friday',
  option,
  program,
  tags: ['black-friday-2026', 'lp-black-friday', january ? 'bf-january-deposit' : 'bf-start-now', 'program-' + (b.program || 'not-sure')],
  opportunityName: `${String(b.name || '').trim()} | Black Friday | ${option} | ${program}`,
  note: `LP Black Friday\nOption: ${option}\nProgram: ${program}\nSMS/email consent: ${b.consent === 'yes' ? 'yes' : 'no'}\nSubmitted: ${b.submitted_at || ''}\n${attribution}`
} }];
